item.command:
/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module TopModule (
    input  logic [7:0] in,
    output logic [2:0] pos
);
    always_comb begin
        casez (in)
            8'b???????1: pos = 3'd0;
            8'b??????10: pos = 3'd1;
            8'b?????100: pos = 3'd2;
            8'b????1000: pos = 3'd3;
            8'b???10000: pos = 3'd4;
            8'b??100000: pos = 3'd5;
            8'b?1000000: pos = 3'd6;
            8'b10000000: pos = 3'd7;
            default:     pos = 3'd0;
        endcase
    end
endmodule
EOF
cp candidate.sv candidate_initial.sv
cat > dev_tb.sv <<'EOF'
module dev_tb;
    logic [7:0] in;
    logic [2:0] pos;
    integer value;
    integer bit_index;
    integer expected;
    bit found;
    TopModule dut (.in(in), .pos(pos));
    initial begin
        for (value = 0; value < 256; value = value + 1) begin
            in = value[7:0];
            expected = 0;
            found = 0;
            for (bit_index = 0; bit_index < 8; bit_index = bit_index + 1) begin
                if (in[bit_index] && "'!found) begin
                    expected = bit_index;
                    found = 1;
                end
            end
            #1;
            if (pos !== expected[2:0])
                $fatal(1, "FAIL in=%b pos=%d expected=%d", in, pos, expected);
        end
        $display("PASS: all 256 binary inputs");
        $finish;
    end
    initial begin
        #1000;
        $fatal(1, "FAIL: development timeout");
    end
endmodule
EOF
timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/iverilog -g2012 -Wall -s dev_tb -o dev_sim candidate.sv dev_tb.sv > dev_compile.log 2>&1
compile_status=$?
cat dev_compile.log
if [ "$compile_status" -eq 0 ]; then
    timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/vvp dev_sim > dev_simulation.log 2>&1
    simulation_status=$?
    cat dev_simulation.log
else
    simulation_status=not_run
fi
printf '"'compile_exit=%s\\nsimulation_exit=%s\\n' \""'$compile_status" "$simulation_status" > dev_status.log
cat dev_status.log'

